INSERT INTO `kategoris` VALUES 
('4', 'Penyelenggaraan (Masyarakat/IKM)', 'penyelenggaraan-masyarakatikm', NULL, 'bi-tag', '#4e9af1', '2026-08-21 11:12:45', '2026-08-21 11:12:45');
INSERT INTO `kblis` VALUES 
('1', '56102', 'Rumah/Warung Makan', 'Kelompok ini mencakup jenis usaha jasa penyediaan makanan dan minuman untuk dikonsumsi di tempat usahanya yang bertempat di sebagian atau seluruh bangunan tetap (tidak berpindah-pindah), yang menyajikan makanan dan minuman di tempat usahanya.', 'KBLI 2025', 'I', 'PENYEDIAAN AKOMODASI DAN PENYEDIAAN MAKAN MINUM', '56', 'Penyediaan Makanan Dan Minuman', '561', 'Restoran dan penyediaan makanan keliling', '5610', 'Restoran dan penyediaan makanan keliling', '56102', 'Rumah/Warung Makan', 'I - PENYEDIAAN AKOMODASI DAN PENYEDIAAN MAKAN MINUM', '1', '2026-08-26 14:43:13', '2026-08-31 04:36:00'),
('2', '47111', 'Perdagangan Eceran Berbagai Macam Barang Yang Utamanya Makanan, Minuman Atau Tembakau Di Minimarket/Supermarket/Hypermarket', 'Kelompok ini mencakup usaha perdagangan eceran berbagai jenis barang kebutuhan yang utamanya bahan makanan/makanan, minuman atau tembakau dengan harga yang sudah ditentukan serta pembeli mengambil dan membayar sendiri kepada kasir (self service/swalayan). Disamping itu juga dapat menjual beberapa barang bukan makanan seperti perabot rumah tangga, mainan anak-anak, dan pakaian. Misalnya minimarket atau supermarket atau hypermarket.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '471', 'Perdagangan Eceran Berbagai Macam Barang di Toko', '4711', 'Perdagangan Eceran Yang Utamanya Makanan, Minuman Atau Tembakau di Toko', '47111', 'Perdagangan Eceran Berbagai Macam Barang Yang Utamanya Makanan, Minuman Atau Tembakau Di Minimarket/Supermarket/Hypermarket', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:56'),
('3', '10792', 'Industri Kue Basah', 'Kelompok ini mencakup usaha pembuatan macam-macam makanan kue basah, yaitu sejenis kue yang relatif tidak tahan lama, seperti wajik, lemper, kue lapis, lumpia, dan martabak (termasuk pembuatan tape dan lempok).', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '10', 'Industri Makanan', '107', 'Industri makanan lainnya', '1079', 'Industri Produk Makanan Lainnya', '10792', 'Industri Kue Basah', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:52'),
('4', '14120', 'Penjahitan Dan Pembuatan Pakaian Sesuai Pesanan', 'Kelompok ini mencakup usaha penjahitan dan pembuatan pakaian sesuai pesanan yang melayani masyarakat umum  dengan tujuan komersil.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '14', 'Industri Pakaian Jadi', '141', 'Industri pakaian jadi dan perlengkapannya, bukan pakaian jadi dari kulit berbulu', '1412', 'Penjahitan dan Pembuatan Pakaian Sesuai Pesanan', '14120', 'Penjahitan Dan Pembuatan Pakaian Sesuai Pesanan', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:52'),
('5', '47413', 'Perdagangan Eceran Piranti Lunak (Software)', 'Kelompok ini mencakup usaha perdagangan eceran khusus piranti lunak (software), seperti bermacam piranti lunak, termasuk piranti lunak untuk video game.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '474', 'Perdagangan Eceran Khusus Peralatan Informasi Dan Komunikasi di Toko', '4741', 'Perdagangan eceran khusus komputer dan perlengkapannya; piranti lunak dan perlengkapan telekomunikasi di toko', '47413', 'Perdagangan Eceran Piranti Lunak (Software)', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:57'),
('6', '96200', 'Aktivitas penatu', 'Kelompok ini mencakup usaha jasa pelayanan pencucian dan dry cleaning, penatu, pencelupan dan tisi barang-barang tekstil jadi (termasuk berbahan kulit bulu binatang) dan tekstil lainnya untuk keperluan rumah tangga maupun industri perorangan, dilakukan dengan peralatan mekanik, baik yang dioperasikan dengan tangan atau dengan koin, seperti taplak meja, seprei, karpet, termasuk juga pakaian dan barang tekstil jadi. Termasuk kegiatan pencucian (shampooing) carpet, dan rug serta curtain gorden; jasa pengumpulan penatu dan pengirimannya; jasa penyediaan linen, seragam kerja dan barang lain yang terkait oleh penatu; reparasi dan alterasi atau pengubahan kecil dari pakaian atau tekstil lain yang terkait dengan pencucian.', 'KBLI 2025', 'S', 'AKTIVITAS JASA LAINNYA', '96', 'Aktivitas Jasa perorangan lainnya', '962', 'Aktivitas penatu', '9620', 'Aktivitas penatu', '96200', 'Aktivitas penatu', 'S - AKTIVITAS JASA LAINNYA', '1', '2026-08-26 14:43:13', '2026-08-31 04:36:09'),
('7', '01122', 'Pertanian Padi Inbrida', 'Kelompok ini mencakup usaha pertanian inbrida (bukan hibrida) mulai dari kegiatan pengolahan lahan, penyemaian, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan sampai dengan dihasilkan komoditas gabah kering panen (GKP). Termasuk kegiatan pembibitan dan pembenihan tanaman padi in hibrida. Padi in hibrida adalah padi yang produksi benihnya dilakukan melalui penyerbukan sendiri atau terjadi secara alami. Terdiri dari Padi varietas Unggul Non Hibrida seperti Memberamo, Menkongga, Ciherang, IR-6, Inpari, Inpara, Inpago dan Padi Varietas Lokas yang telah ada dan dibudidayakan secara turun temurun oleh petani. ', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0112', 'Pertanian Padi', '01122', 'Pertanian Padi Inbrida', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:47'),
('8', '10710', 'Industri Produk Roti Dan Kue', 'Kelompok ini mencakup usaha pembuatan berbagai macam roti, kue dan produk bakeri lainnya seperti industri roti tawar dan roti kadet; industri kue, pie, tart; industri biskuit dan produk roti kering lainnya; industri pengawetan kue kering dan cake; industri produk makanan ringan baik yang manis atau asin; industri tortillas; dan industri produk roti yang dibekukan, seperti pancake, waffle dan roti kadet.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '10', 'Industri Makanan', '107', 'Industri makanan lainnya', '1071', 'Industri Produk Roti dan Kue', '10710', 'Industri Produk Roti Dan Kue', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:51'),
('9', '47411', 'Perdagangan Eceran Komputer Dan Perlengkapannya', 'Kelompok ini mencakup usaha perdagangan eceran khusus macam-macam komputer, peralatan dan perlengkapannya.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '474', 'Perdagangan Eceran Khusus Peralatan Informasi Dan Komunikasi di Toko', '4741', 'Perdagangan eceran khusus komputer dan perlengkapannya; piranti lunak dan perlengkapan telekomunikasi di toko', '47411', 'Perdagangan Eceran Komputer Dan Perlengkapannya', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:57'),
('10', '45401', 'Perdagangan Besar Sepeda Motor Baru', 'Kelompok ini mencakup usaha perdagangan besar sepeda motor baru, termasuk motor sepeda atau moped.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '45', 'Perdagangan, Reparasi dan Perawatan Mobil dan Sepeda Motor', '454', 'Perdagangan, Reparasi dan Perawatan Sepeda Motor dan Perdagangan Suku Cadang dan Aksesorinya', '4540', 'Perdagangan, Reparasi dan Perawatan Sepeda Motor dan Perdagangan Suku Cadang dan Aksesorinya', '45401', 'Perdagangan Besar Sepeda Motor Baru', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-26 14:43:13', '2026-08-31 04:35:55'),
('11', '47112', 'Perdagangan Eceran Berbagai Macam Barang Yang Utamanya Makanan, Minuman Atau Tembakau Bukan Di Minimarket/Supermarket/Hypermarket (Tradisional)', 'Kelompok ini mencakup usaha perdagangan eceran berbagai jenis barang kebutuhan yang utamanya bahan makanan/makanan, minuman atau tembakau di dalam bangunan bukan swalayan/minimarket/supermarket/hypermarket. Disamping itu juga dapat menjual beberapa barang bukan makanan seperti pakaian, perabot rumah tangga, dan mainan anak. Misalnya warung atau toko bahan kebutuhan pokok.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '471', 'Perdagangan Eceran Berbagai Macam Barang di Toko', '4711', 'Perdagangan Eceran Yang Utamanya Makanan, Minuman Atau Tembakau di Toko', '47112', 'Perdagangan Eceran Berbagai Macam Barang Yang Utamanya Makanan, Minuman Atau Tembakau Bukan Di Minimarket/Supermarket/Hypermarket (Tradisional)', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:56'),
('12', '47211', 'Perdagangan Eceran Padi Dan Palawija', 'Kelompok ini mencakup usaha perdagangan eceran khusus padi dan palawija, di dalam bangunan seperti gabah, jagung, ubi jalar, ubi kayu, talas, kacang kedelai, kacang tanah, kacang hitam dan kacang polong.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '472', 'Perdagangan Eceran Khusus Makanan, Minuman Dan Tembakau di Toko', '4721', 'Perdagangan eceran khusus komoditi makanan dari hasil pertanian di toko', '47211', 'Perdagangan Eceran Padi Dan Palawija', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:56'),
('13', '47241', 'Perdagangan Eceran Beras', 'Kelompok ini mencakup usaha perdagangan eceran khusus berbagai jenis beras di dalam bangunan, seperti beras cianjur, beras cisadane, beras saigon dan beras ketan.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '472', 'Perdagangan Eceran Khusus Makanan, Minuman Dan Tembakau di Toko', '4724', 'Perdagangan Eceran Khusus Makanan Hasil Industri di Toko', '47241', 'Perdagangan Eceran Beras', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:57'),
('14', '47528', 'Perdagangan Eceran Berbagai Macam Material Bangunan', 'Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam material bangunan, seperti semen, pasir , paku, cat dan lain-lain.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '475', 'Perdagangan Eceran Khusus Perlengkapan Rumah Tangga Lainnya di Toko', '4752', 'Perdagangan eceran khusus barang dan bahan bangunan, cat dan kaca di toko', '47528', 'Perdagangan Eceran Berbagai Macam Material Bangunan', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:57'),
('15', '47711', 'Perdagangan Eceran Pakaian', 'Kelompok ini mencakup usaha perdagangan eceran khusus pakaian, baik terbuat dari tekstil, kulit, maupun kulit buatan, seperti kemeja, celana, jas, mantel, jaket, piyama, kebaya, blus, rok, daster, singlet, kutang/BH, gaun, rok dalam, baju bayi, pakaian tari, pakaian adat, mukena dan jubah.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '477', 'Perdagangan Eceran Khusus Barang Lainnya di Toko', '4771', 'Perdagangan eceran khusus pakaian, alas kaki dan barang dari kulit di toko', '47711', 'Perdagangan Eceran Pakaian', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:57'),
('16', '47811', 'Perdagangan Eceran Kaki Lima Dan Los Pasar Komoditi Padi Dan Palawija', 'Kelompok ini mencakup usaha perdagangan eceran padi dan palawija, yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti gabah, jagung, ubi jalar, ubi kayu, talas, kacang kedelai, kacang tanah, kacang hitam dan kacang polong.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '478', 'Perdagangan Eceran Kaki lima dan los pasar', '4781', 'Perdagangan eceran kaki lima dan los pasar komoditi hasil pertanian', '47811', 'Perdagangan Eceran Kaki Lima Dan Los Pasar Komoditi Padi Dan Palawija', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:58'),
('17', '47823', 'Perdagangan Eceran Kaki Lima Dan Los Pasar Kopi, Gula Pasir, Gula Merah Dan Sejenisnya', 'Kelompok ini mencakup usaha perdagangan eceran kopi, gula pasir, gula merah dan teh yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar).', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '478', 'Perdagangan Eceran Kaki lima dan los pasar', '4782', 'Perdagangan eceran kaki lima dan los pasar makanan, minuman dan produk tembakau hasil industri pengolahan', '47823', 'Perdagangan Eceran Kaki Lima Dan Los Pasar Kopi, Gula Pasir, Gula Merah Dan Sejenisnya', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:58'),
('18', '10391', 'Industri Tempe Kedelai', 'Kelompok ini mencakup usaha pembuatan tempe dari kedelai. Usaha pembuatan tempe yang bahan bakunya selain kedelai (dari kacang tanah/kacang-kacangan lainnya), seperti tempe bongkrek, dimasukkan dalam kelompok 10393.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '10', 'Industri Makanan', '103', 'Industri pengolahan dan pengawetan buah-buahan dan sayuran', '1039', 'Industri Pengolahan dan Pengawetan Lainnya Buah-buahan dan Sayuran', '10391', 'Industri Tempe Kedelai', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:51'),
('19', '10392', 'Industri Tahu Kedelai', 'Kelompok ini mencakup usaha pembuatan tahu dari kedelai. Usaha pembuatan tahu yang bahan bakunya selain kedelai (dari kacang tanah/kacang-kacangan lainnya) dimasukkan dalam kelompok 10393.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '10', 'Industri Makanan', '103', 'Industri pengolahan dan pengawetan buah-buahan dan sayuran', '1039', 'Industri Pengolahan dan Pengawetan Lainnya Buah-buahan dan Sayuran', '10392', 'Industri Tahu Kedelai', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:51'),
('20', '10772', 'Industri Bumbu Masak Dan Penyedap Masakan', 'Kelompok ini mencakup usaha pembuatan bumbu masak dalam keadaan sudah diramu atau belum, baik berbentuk bubuk ataupun lainnya, seperti bumbu gulai, bumbu kari, bumbu merica, bubuk jahe, bubuk jinten, bubuk pala, bubuk cabe dan bubuk kayu manis. Termasuk usaha industri penyedap masakan baik yang asli, natura maupun sintesa khemis, seperti vetsin dan serbuk panili dan industri bumbu-bumbu, saus dan rempah-rempah, seperti mayonais, tepung mustar, mustar olahan, sauce tomat, sauce selada, dan pengganti garam yang digunakan sebagai bumbu pada produk pangan.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '10', 'Industri Makanan', '107', 'Industri makanan lainnya', '1077', 'Industri Bumbu-bumbuan dan Produk Masak Lainnya', '10772', 'Industri Bumbu Masak Dan Penyedap Masakan', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:52'),
('21', '11040', 'Industri Minuman Ringan', 'Kelompok ini mencakup usaha industri minuman yang tidak mengandung alkohol, kecuali bir dan anggur tanpa alkohol. Termasuk industri minuman ringan beraroma tanpa alkohol dan atau rasa manis, seperti lemonade, orangeade, cola, minuman buah, air tonik, limun, air soda, krim soda dan air anggur, minuman yang dikarbonasi maupun tidak, dan minuman yang mengandung konsentrat, dan minuman serbuk.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '11', 'Industri Minuman', '110', 'Industri Minuman', '1104', 'Industri Minuman Ringan', '11040', 'Industri Minuman Ringan', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:52'),
('22', '13921', 'Industri Barang Jadi Tekstil Untuk Keperluan Rumah Tangga', 'Kelompok ini mencakup usaha pembuatan barang-barang jadi tekstil, seperti selimut, seprei, taplak meja, sarung bantal, bed cover, gorden, handuk, sarung alas kursi, sajadah/penutup lantai yang dibuat dengan proses penggabungan dan/atau penjahitan beberapa bahan tekstil, selubung mobil dan selimut listrik dan lain-lain. Sajadah/penutup lantai dari karpet/permadani dimasukkan dalam kelompok 13930.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '13', 'Industri tekstil', '139', 'Industri Tekstil Lainnya', '1392', 'Industri Pembuatan Barang Tekstil, Bukan Pakaian Jadi', '13921', 'Industri Barang Jadi Tekstil Untuk Keperluan Rumah Tangga', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:52'),
('23', '16293', 'Industri Kerajinan Ukiran Dari Kayu Bukan Mebeller', 'Kelompok ini mencakup usaha pembuatan macam-macam barang kerajinan dan ukir-ukiran dari kayu, seperti relief, topeng, patung, wayang, vas bunga, pigura dan kap lampu.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '16', 'Industri Kayu, Barang dari Kayu dan Gabus (Tidak Termasuk Furnitur) dan Barang Anyaman dari Bambu, Rotan dan Sejenisnya', '162', 'Industri Barang dari Kayu; Industri Barang dari Gabus dan barang anyaman dari jerami, rotan, bambu dan sejenis lainnya', '1629', 'Industri Barang Lainnya dari Kayu; Industri Barang dari Gabus dan Barang Anyaman dari Jerami, Rotan, Bambu dan Sejenisnya', '16293', 'Industri Kerajinan Ukiran Dari Kayu Bukan Mebeller', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:52'),
('24', '31001', 'Industri Furnitur Dari Kayu', 'Kelompok ini mencakup usaha pembuatan furnitur dari kayu untuk rumah tangga dan kantor, seperti meja, kursi, bangku, tempat tidur, lemari, rak, kabinet, penyekat ruangan dan sejenisnya.', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '31', 'Industri Furnitur', '310', 'Industri Furnitur', '3100', 'Industri Furnitur', '31001', 'Industri Furnitur Dari Kayu', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:54'),
('25', '45201', 'Reparasi Mobil', 'Kelompok ini mencakup usaha reparasi dan perawatan mobil, seperti reparasi mekanik, reparasi elektrik, reparasi sistem injeksi elektronik, servis regular, reparasi badan mobil, reparasi bagian kendaraan bermotor, penyemprotan dan pengecatan, reparasi kaca dan jendela dan reparasi tempat duduk kendaraan bermotor. Termasuk reparasi, pemasangan atau penggantian ban dan pipa, perawatan anti karat, pemasangan bagian dan aksesori yang bukan bagian dari proses pembuatan dan usaha perawatan lainnya.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '45', 'Perdagangan, Reparasi dan Perawatan Mobil dan Sepeda Motor', '452', 'Reparasi dan Perawatan Mobil', '4520', 'Reparasi dan Perawatan Mobil', '45201', 'Reparasi Mobil', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:55'),
('26', '45407', 'Reparasi Dan Perawatan Sepeda Motor', 'Kelompok ini mencakup usaha pemeliharaan dan reparasi sepeda motor, termasuk pencucian sepeda motor dan usaha perawatan lainnya.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '45', 'Perdagangan, Reparasi dan Perawatan Mobil dan Sepeda Motor', '454', 'Perdagangan, Reparasi dan Perawatan Sepeda Motor dan Perdagangan Suku Cadang dan Aksesorinya', '4540', 'Perdagangan, Reparasi dan Perawatan Sepeda Motor dan Perdagangan Suku Cadang dan Aksesorinya', '45407', 'Reparasi Dan Perawatan Sepeda Motor', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-27 15:21:03', '2026-08-31 04:35:55'),
('27', '95210', 'Reparasi Alat-alat Elektronik Konsumen', 'Kelompok ini mencakup usaha khusus jasa reparasi dan perawatan alat elektronik konsumen, seperti televisi dan radio penerima (termasuk pemasangan antena),, perekam kaset video (VCR), CD player dan kamera video jenis untuk pengguna rumah tangga. ', 'KBLI 2025', 'S', 'AKTIVITAS JASA LAINNYA', '95', 'Reparasi Komputer Dan Barang Keperluan Pribadi Dan Perlengkapan Rumah Tangga', '952', 'Reparasi barang keperluan pribadi dan perlengkapan rumah tangga', '9521', 'Reparasi Alat-alat Elektronik Konsumen', '95210', 'Reparasi Alat-alat Elektronik Konsumen', 'S - AKTIVITAS JASA LAINNYA', '1', '2026-08-27 15:21:03', '2026-08-31 04:36:09'),
('28', '47215', 'Perdagangan Eceran Hasil Perikanan', 'Kelompok ini mencakup usaha perdagangan eceran khusus hasil perikanan di dalam bangunan, seperti udang segar, ikan segar, cumi-cumi segar, nener (benih bandeng), benur (benih udang), benih ikan, dan rumput laut.', 'KBLI 2025', 'G', 'PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '47', 'Perdagangan Eceran, Bukan Mobil Dan Motor', '472', 'Perdagangan Eceran Khusus Makanan, Minuman Dan Tembakau di Toko', '4721', 'Perdagangan eceran khusus komoditi makanan dari hasil pertanian di toko', '47215', 'Perdagangan Eceran Hasil Perikanan', 'G - PERDAGANGAN BESAR DAN ECERAN; REPARASI DAN PERAWATAN MOBIL DAN SEPEDA MOTOR', '1', '2026-08-28 06:10:23', '2026-08-31 04:35:57'),
('29', '03111', 'Penangkapan Pisces/Ikan Bersirip Di Laut', 'Kelompok ini mencakup usaha atau kegiatan penangkapan pisces/ikan bersirip dengan alat penangkapan ikan: jaring lingkar (surrounding nets) termasuk pukat cincin pelagis besar dengan satu kapal, pukat cincin pelagis kecil dengan satu kapal, pukat cincin teri, pukat cincin pelagis besar dengan dua kapal, pukat cincin pelagis kecil dengan dua kapal, yang menangkap jenis ikan cakalang, madidihang, tongkol krai, tongkol komo, pelagis besar lainya, layang, kembung, selar, lemuru, kembang, pelagis kecil lainnya, dll); pukat tarik (seine nets) termasuk pukat tarik pantai (beach seine), dogol (danish seine), payang, cantrang, yang menangkap jenis ikan kakap putih, kakap merah, kuwe, manyung, cucut, kerapu, pari, kurisi, remang, layang, kembung, selar, lemuru, tembang, siro, dll; pukat hela (trawls) berupa pukat hela dasar udang, yang menangkap jenis ikan pelagis kecil, pelagis besar, demersal, dll; jaring angkat (lift nets) termasuk anco (portable lift net), bagan berperahu, bouke ami, bagan tancap, yang menangkap jenis ikan tongkol krai, tongkol komo, madidihang, cakalang, kembung, pelagis besar lainnya, pelagis kecil lainnya, dll; alat yang dijatuhkan atau ditebarkan (falling gears), termasuk jala jatuh berkapal (cast net) dan jala tebar (falling gear not specified) menangkap jenis ikan beronang, biji nangka, pelagis kecil lainya, dll; jaring insang (gillnets and entangling nets), termasuk jaring insang tetap (set gillnet (anchored)), jaring insang hanyut (drift gillnet), jaring insang lingkar (encircling gillnets), jaring insang berpancang (fixed gillnet (on stakes)), jaring insang berlapis (trammel net), combined gillnets-trammel net, yang menangkap jenis ikan cucut, pari, demersal lainya, cakalang, tongkol krai, tongkol komo, madidihang, tenggiri bulat, cucut, pelagis besar lainnya, pelagis kecil lainnya, dll; perangkap (traps), termasuk set net, bubu (pot), bubu bersayap (fyke net), pukat labuh (long bag set net), togo, ambai, jermal, pengerih, sero, yang menangkap jenis ikan Belanak, kuwe, julung-julung, pelagis kecil lainnya dll; pancing (hooks and lines), termasuk pancing ulur nontuna, pancing ulur tuna, pancing berjoran, huhate, pancing cumi, pancing cumi mekanis (squid jigging), huhate mekanis, rawai dasar (set longline), rawai tuna, tonda, pancing layang-layang, yang menangkap jenis ikan cakalang, tongkol krai, tongkol komo, tuna lainnya, tenggiri, pelagis besar lainnya, ikan tuna mata besar, madidihang, albacora, marlin, meka, kakap putih, kakap merah, kuwe, manyung, cucut, kerapu, pari, kurisi, remang, demersal lainya, karang lainnya, kerapu, kurisi, lencam, dll; alat penangkapan ikan lainnya (miscellaneous gears), termasuk tombak (harpoon), ladung, panah, pukat dorong (pushnet), muro ami (drive-in net), seser, yang menangkap jenis ikan ekor kuning, pisang-pisang, kapas-kapas, ikan karang dan ikan demersal, dll di laut, muara sungai, laguna dan tempat lain yang dipengaruhi pasang surut. Termasuk pula kegiatan kapal yang digunakan baik untuk menangkap ikan maupun pengolahan dan pengawetan ikan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '03', 'Perikanan', '031', 'Perikanan Tangkap', '0311', 'Penangkapan ikan di laut', '03111', 'Penangkapan Pisces/Ikan Bersirip Di Laut', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-28 08:24:36', '2026-08-31 04:35:49'),
('30', '10510', 'Industri Pengolahan Susu Segar dan Krim', 'Kelompok ini mencakup usaha industri pengolahan susu cair segar, susu dipasteurisasi, disterilisasi, homogenisasi dan atau pemanasan ultra (UHT) dan industri pengolahan krim dari susu cair segar, pasteurisasi, sterilisasi dan homogenisasi, dalam bentuk cair atau semi cair dan produk sejenis lainnya. ', 'KBLI 2025', 'C', 'INDUSTRI PENGOLAHAN', '10', 'Industri Makanan', '105', 'Industri pengolahan susu, produk dari susu dan es krim', '1051', 'Industri Pengolahan Susu Segar dan Krim', '10510', 'Industri Pengolahan Susu Segar dan Krim', 'C - INDUSTRI PENGOLAHAN', '1', '2026-08-28 08:24:36', '2026-08-31 04:35:51'),
('31', '01111', 'Pertanian Jagung', 'Kelompok ini mencakup usaha pertanian komoditas jagung mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman jagung. Termasuk kegiatan pembibitan dan pembenihan tanaman jagung.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01111', 'Pertanian Jagung', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('32', '01112', 'Pertanian Gandum', 'Kelompok ini mencakup usaha pertanian gandum mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman serealia gandum, seperti sorgum/cantel, gandum (wheat/oats), jelai (barley), gandum hitam (rye), jawawut (millet) dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman gandum.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01112', 'Pertanian Gandum', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('33', '01113', 'Pertanian Kedelai', 'Kelompok ini mencakup usaha pertanian kedelai mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman kedelai (kacang palawija). Termasuk kegiatan pembibitan dan pembenihan tanaman kedelai.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01113', 'Pertanian Kedelai', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('34', '01114', 'Pertanian Kacang Tanah', 'Kelompok ini mencakup usaha pertanian kacang tanah mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman kacang tanah (kacang palawija). Termasuk kegiatan pembibitan dan pembenihan tanaman kacang tanah.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01114', 'Pertanian Kacang Tanah', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('35', '01115', 'Pertanian Kacang Hijau', 'Kelompok ini mencakup usaha pertanian kacang hijau mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman kacang hijau (kacang palawija). Termasuk kegiatan pembibitan dan pembenihan tanaman kacang hijau.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01115', 'Pertanian Kacang Hijau', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('36', '01116', 'Pertanian Aneka Kacang Hortikultura', 'Kelompok ini mencakup usaha pertanian aneka kacang hortikultura mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman aneka kacang hortikultura, seperti buncis, buncis besar, kacang panjang, kacang merah, gude, kara, kapri, kecipir, cow peas, miju-miju, lupin, kacang polong, pigeon peas dan tanaman aneka kacang lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman aneka kacang hortikultura.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01116', 'Pertanian Aneka Kacang Hortikultura', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('37', '01117', 'Pertanian Biji-bijian Penghasil Minyak Makan', 'Kelompok ini mencakup usaha pertanian biji-bijian penghasil minyak makan mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman biji-bijian penghasil minyak makan, seperti biji wijen, biji bunga matahari dan tanaman biji-bijian penghasil minyak makan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman biji-bijian penghasil minyak makan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01117', 'Pertanian Biji-bijian Penghasil Minyak Makan', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('38', '01118', 'Pertanian Biji-bijian Penghasil Bukan Minyak Makan', 'Kelompok ini mencakup usaha pertanian biji-bijian penghasil bukan minyak makan mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman biji-bijian penghasil bukan minyak makan, seperti biji kapas, biji rami, biji mustard, niger seeds, biji jarak pohon dan tanaman biji-bijian penghasil bukan minyak makan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman biji-bijian penghasil bukan minyak makan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01118', 'Pertanian Biji-bijian Penghasil Bukan Minyak Makan', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('39', '01119', 'Pertanian Serealia Lainnya, Aneka Kacang dan Biji-Bijian Penghasil Minyak Lainnya', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman serealia lainnya bukan padi, jagung dan gandum, tanaman aneka kacang palawija lainnya dan pertanian tanaman lainnya yang belum diklasifikasikan pada kelompok 01111 s.d. 01118. Termasuk kegiatan pembibitan dan pembenihan tanaman serealia dan biji-bijian penghasil minyak lainnya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0111', 'Pertanian serealia (bukan padi), aneka kacang dan biji-bijian penghasil minyak', '01119', 'Pertanian Serealia Lainnya, Aneka Kacang dan Biji-Bijian Penghasil Minyak Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('40', '01121', 'Pertanian Padi Hibrida', 'Kelompok ini mencakup usaha pertanian padi hibrida mulai dari kegiatan pengolahan lahan, penyemaian, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan sampai dengan dihasilkan komoditas gabah kering panen (GKP). Termasuk kegiatan pembibitan dan pembenihan tanaman padi hibrida. Padi hibrida adalah keturunan pertama (F1) yang dihasilkan dari persilangan antara dua galur atau lebih tetua pembentuknya dan/atau galur/inbrida homozigot. Contohnya: Bernas Super, Bernas Prima, Sembada B3, SL 11 SHS. Turunan dari padi hibrida tidak termasuk sebagai padi hibrida. ', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0112', 'Pertanian Padi', '01121', 'Pertanian Padi Hibrida', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('41', '01131', 'Pertanian Hortikultura Sayuran Daun', 'Kelompok ini mencakup usaha pertanian hortikultura dan sayuran daun mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan, dan pasca panen jika menjadi satu kesatuan kegiatan tanaman hortikultura sayuran yang dipanen sekali, seperti petsai/sawi, asparagus, kubis/kol, kembang kol dan brokoli, selada dan seledri/chicory, daun bawang, bayam, kangkung, tumbuhan yang bunganya dimakan sebagai sayur dan sayuran daun dan batang lainnya. Bayam dan kangkung yang dipanen dengan akarnya juga dimasukkan dalam kelompok ini. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura sayuran daun.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01131', 'Pertanian Hortikultura Sayuran Daun', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('42', '01132', 'Pertanian Hortikultura Buah', 'Kelompok ini mencakup usaha pertanian hortikultura buah mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman hortikultura buah, seperti semangka, belewah, melon, timun suri dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura buah.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01132', 'Pertanian Hortikultura Buah', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('43', '01133', 'Pertanian Hortikultura Sayuran Buah', 'Kelompok ini mencakup usaha pertanian hortikultura sayuran buah mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman hortikultura buah yang dipakai sebagai sayuran (labu), seperti mentimun, terung, tomat, belimbing sayur dan labu sayur (siam), waluh/labu kuning, gambas/oyong dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura sayuran buah.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01133', 'Pertanian Hortikultura Sayuran Buah', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('44', '01134', 'Pertanian Hortikultura Sayuran Umbi', 'Kelompok ini mencakup usaha pertanian hortikultura sayuran umbi mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, pemanenan, dan pasca panen jika menjadi satu kesatuan kegiatan tanaman umbi-umbian hortikultura, seperti kentang, kentang manis, wortel, lobak cina, rebung, bawang putih, bawang bombay atau bawang merah, bawang perai dan sayuran alliaceous lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura sayuran umbi.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01134', 'Pertanian Hortikultura Sayuran Umbi', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('45', '01135', 'Pertanian Aneka Umbi Palawija', 'Kelompok ini mencakup usaha pertanian aneka umbi palawija mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman aneka umbi palawija, seperti ubi kayu, ubi jalar, talas, ganyong dan irut, gembili dan tanaman palawija, iles-iles, porang dan umbi-umbian palawija lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman aneka umbi palawija.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01135', 'Pertanian Aneka Umbi Palawija', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('46', '01136', 'Pertanian Jamur', 'Kelompok ini mencakup usaha pertanian jamur mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman jamur dan truffle, seperti jamur merang, jamur tiram, jamur shitake, jamur kuping dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman jamur.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01136', 'Pertanian Jamur', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('47', '01137', 'Pertanian Bit Gula Dan Tanaman Pemanis Bukan Tebu', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman bit gula dan tanaman pemanis lainnya bukan tebu, seperti stevia dan sorgum manis. Termasuk kegiatan pembibitan dan pembenihan tanaman bit gula dan tanaman pemanis bukan tebu.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01137', 'Pertanian Bit Gula Dan Tanaman Pemanis Bukan Tebu', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('48', '01139', 'Pertanian Sayuran, Buah dan Aneka Umbi Lainnya', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman sayuran, buah dan aneka umbi lainnya yang dipanen lebih dari sekali; dan pertanian sayuran lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman sayuran lainnya, kecuali bibit tanaman bit. ', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0113', 'Pertanian sayuran, buah dan aneka umbi', '01139', 'Pertanian Sayuran, Buah dan Aneka Umbi Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('49', '01140', 'Perkebunan Tebu', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan jika menjadi satu kesatuan kegiatan tanaman tebu. Termasuk kegiatan pembibitan dan pembenihan tebu.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0114', 'Perkebunan tebu', '01140', 'Perkebunan Tebu', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('50', '01150', 'Perkebunan Tembakau', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan jika menjadi satu kesatuan kegiatan tanaman tembakau. Termasuk kegiatan pembersihan dan perajangan tembakau yang tidak dapat dipisahkan dari kegiatan perkebunannya. Kegiatan pembibitan dan pembenihan tanaman tembakau juga tercakup dalam kelompok ini.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0115', 'Perkebunan tembakau', '01150', 'Perkebunan Tembakau', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('51', '01160', 'Pertanian Tanaman Berserat', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan jika menjadi satu kesatuan kegiatan tanaman  berserat sebagai bahan baku tekstil, seperti kapuk, kapas, rosela, rami, yute, linen, agave, abaca dan kenaf, pertanian sisal dan tanaman bahan baku tekstil lainnya termasuk genus agave dan pertanian tanaman serat lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman berserat.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0116', 'Pertanian tanaman berserat', '01160', 'Pertanian Tanaman Berserat', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('52', '01191', 'Pertanian Tanaman Pakan Ternak', 'Kelompok ini mencakup bidang usaha produksi  hijauan pakan ternak mulai dari kegiatan penyiapan dan pengolahan lahan, penyemaian, penanaman, pemeliharaan, pemanenan dan pengolahan pasca panen. Meliputi rumput pakan ternak dan leguminosa/kacang-kacangan tanaman pakan ternak seperti Rumput Gajah, Rumput Raja, Rumput Odot, Rumput Setaria, Alfalfa, Kaliandra, Gamal, Lamtoro, Indigofera Zollingeriana dll.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0119', 'Pertanian tanaman semusim lainnya', '01191', 'Pertanian Tanaman Pakan Ternak', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('53', '01192', 'Perbenihan Tanaman Pakan Ternak dan Pembibitan Bit (Bukan Bit Gula)', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan dan pengolahan lahan, penyemaian, penanaman, pemeliharaan, pemanenan dan pengolahan pascapanen, perbenihan tanaman pakan ternak dan pembibitan bit (bukan bit gula). Perbenihan tanaman pakan ternak meliputi rumput pakan ternak dan leguminosa/kacang-kacangan tanaman pakan ternak seperti Rumput Gajah, Rumput Raja, Rumput Odot, Rumput Setaria, Alfalfa, Kaliandra, Gamal, Lamtoro, Indigofera Zollingeriana dll.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0119', 'Pertanian tanaman semusim lainnya', '01192', 'Perbenihan Tanaman Pakan Ternak dan Pembibitan Bit (Bukan Bit Gula)', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('54', '01193', 'Pertanian Tanaman Bunga', 'Kelompok  ini mencakup pertanian tanaman bunga, yang produksinya adalah bunga potong dan kuncup bunga. Tanaman bunga pada kelompok ini misalnya anggrek, anyelir, gerbera/hebras, gladiol, krisan, mawar, melati, sedap malam dan tanaman bunga lainnya. Termasuk tanaman bunga lainnya yang diambil bunganya. Pertanian tanaman bunga yang hasilnya adalah tanaman bunga hidup masuk ke golongan 013.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0119', 'Pertanian tanaman semusim lainnya', '01193', 'Pertanian Tanaman Bunga', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('55', '01194', 'Pertanian Pembibitan Tanaman Bunga', 'Kelompok ini mencakup usaha pertanian pembibitan tanaman bunga.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0119', 'Pertanian tanaman semusim lainnya', '01194', 'Pertanian Pembibitan Tanaman Bunga', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('56', '01199', 'Pertanian tanaman semusim lainnya ytdl', 'Kelompok ini mencakup pertanian tanaman semusim lainnya yang belum terklasifikasi di tempat lain dan kegiatan pembibitannya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '011', 'Pertanian Tanaman Semusim', '0119', 'Pertanian tanaman semusim lainnya', '01199', 'Pertanian tanaman semusim lainnya ytdl', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('57', '01210', 'Pertanian Buah Anggur', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan atau pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah anggur. Termasuk kegiatan pembibitan dan pembenihan tanaman buah anggur.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0121', 'Pertanian Buah Anggur', '01210', 'Pertanian Buah Anggur', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('58', '01220', 'Pertanian Buah-Buahan Tropis dan Subtropis', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan/pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah-buahan tropis dan subtropis, seperti rambutan, alpukat, durian, duku, pisang dan pisang raja, kurma, buah ara, pepaya, jambu biji, jambu air, lengkeng, nangka, nenas, mangga, manggis, sawo, belimbing, salak, sirsak, buah naga dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buat tropis dan subtropis.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0122', 'Pertanian Buah-Buahan Tropis dan Subtropis', '01220', 'Pertanian Buah-Buahan Tropis dan Subtropis', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('59', '01230', 'Pertanian Buah Jeruk', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan/pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah jeruk besar dan jeruk keprok atau jeruk siam, seperti jeruk bali, jeruk lemon dan limau, jeruk orange, jeruk keprok, jeruk tangerin, jeruk mandarin dan clementine, dan buah jeruk lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah jeruk.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0123', 'Pertanian Buah Jeruk', '01230', 'Pertanian Buah Jeruk', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('60', '01240', 'Pertanian Buah Apel dan Buah Batu (Pome and Stone Fruits)', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan/pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah apel dan buah batu, seperti apel, aprikot, cherry, peach dan nectarine, pear dan quince, plum dan sloe, markisa, kepel, terong Belanda dan buah delima, dan buah batu lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah apel dan buah batu.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0124', 'Pertanian Buah Apel dan Buah Batu (Pome and Stone Fruits)', '01240', 'Pertanian Buah Apel dan Buah Batu (Pome and Stone Fruits)', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('61', '01251', 'Pertanian Buah Beri', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan atau pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah beri, seperti blueberry, gooseberry, kiwi, raspberry, strawberry dan beri lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah beri.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0125', 'Pertanian Sayuran dan Buah Semak dan Buah Biji Kacang-Kacangan Lainnya', '01251', 'Pertanian Buah Beri', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('62', '01252', 'Pertanian Buah Biji Kacang-Kacangan', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman buah biji kacang-kacangan  yang dapat dimakan, seperti almond, kacang mede, chestnut, kenari, walnut dan kacang-kacangan yang lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah biji kacang-kacangan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0125', 'Pertanian Sayuran dan Buah Semak dan Buah Biji Kacang-Kacangan Lainnya', '01252', 'Pertanian Buah Biji Kacang-Kacangan', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('63', '01253', 'Pertanian Sayuran Tahunan', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman sayuran tahunan, seperti kluwih atau timbul, sukun, nangka sayur, petai, jengkol, melinjo dan sejenisnya. Kegiatan pembibitan dan pembenihan tanaman sayuran tahunan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0125', 'Pertanian Sayuran dan Buah Semak dan Buah Biji Kacang-Kacangan Lainnya', '01253', 'Pertanian Sayuran Tahunan', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('64', '01259', 'Pertanian Buah Semak Lainnya', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman buah semak lainnya, termasuk locust beans. Termasuk kegiatan pembibitan dan pembenihan tanaman buah semak lainnya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0125', 'Pertanian Sayuran dan Buah Semak dan Buah Biji Kacang-Kacangan Lainnya', '01259', 'Pertanian Buah Semak Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('65', '01261', 'Perkebunan Buah Kelapa', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan buah kelapa. Termasuk kegiatan pembibitan dan pembenihan tanaman buah kelapa.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0126', 'Perkebunan buah-buahan penghasil minyak (oleaginous)', '01261', 'Perkebunan Buah Kelapa', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('66', '01262', 'Perkebunan Buah Kelapa Sawit', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan buah kelapa sawit. Termasuk kegiatan pembibitan dan pembenihan tanaman buah kelapa sawit.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0126', 'Perkebunan buah-buahan penghasil minyak (oleaginous)', '01262', 'Perkebunan Buah Kelapa Sawit', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('67', '01269', 'Perkebunan Buah Oleaginous Lainnya', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman buah oleaginous lain, seperti buah zaitun dan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah oleoginous lainnya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0126', 'Perkebunan buah-buahan penghasil minyak (oleaginous)', '01269', 'Perkebunan Buah Oleaginous Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('68', '01270', 'Pertanian Tanaman Untuk Bahan Minuman', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman untuk bahan minuman, seperti tanaman kopi, teh, mate dan kakao. Termasuk kegiatan pembibitan dan pembenihan tanaman untuk bahan minuman.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0127', 'Pertanian Tanaman Untuk Bahan Minuman', '01270', 'Pertanian Tanaman Untuk Bahan Minuman', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('69', '01281', 'Perkebunan Lada', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan lada atau merica (piper spp). Termasuk kegiatan pembibitan dan pembenihan tanaman lada.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01281', 'Perkebunan Lada', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('70', '01282', 'Perkebunan Cengkeh', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan cengkeh. Termasuk kegiatan pembibitan dan pembenihan tanaman cengkeh.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01282', 'Perkebunan Cengkeh', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('71', '01283', 'Pertanian Cabai', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, pemanenan dan pasca panen sayuran cabai (capsicum spp), seperti cabai besar, cabai rawit dan paprika. Termasuk kegiatan pembibitan dan pembenihan tanaman cabai.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01283', 'Pertanian Cabai', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('72', '01284', 'Perkebunan Tanaman Aromatik/Penyegar', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman perkebunan minyak atsiri, seperti sereh wangi, nilam, menthol, kenanga, ilang-ilang, gandapura, lawang. Termasuk kegiatan pembibitan dan pembenihan tanaman aromatik/penyegar.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01284', 'Perkebunan Tanaman Aromatik/Penyegar', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('73', '01285', 'Pertanian Tanaman Obat atau Biofarmaka Rimpang', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman obat atau biofarmaka rimpang (termasuk pula tanaman bahan insektisida dan fungisida dan yang sejenis), seperti jahe, kunyit, temulawak, temugiring, temuireng, temukunci, kencur, lengkuas, lempuyang, dlingo dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman obat atau biofarmaka rimpang.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01285', 'Pertanian Tanaman Obat atau Biofarmaka Rimpang', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('74', '01286', 'Pertanian Tanaman Obat atau Biofarmaka Non Rimpang', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman obat atau biofarmaka non rimpang (termasuk pula tanaman bahan insektisida dan fungisida dan yang sejenis), seperti kina, adas, kapulaga, orang-aring, iles-iles, pinang, gambir, lidah buaya, kejibeling, sambiloto, kumis kucing, mengkudu atau pace, mahkota dewa dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman obat atau biofarmaka non rimpang.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01286', 'Pertanian Tanaman Obat atau Biofarmaka Non Rimpang', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('75', '01287', 'Pertanian Tanaman Narkotika dan Tanaman Obat Terlarang', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman narkotika dan tanaman obat terlarang.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01287', 'Pertanian Tanaman Narkotika dan Tanaman Obat Terlarang', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('76', '01289', 'Pertanian Tanaman Rempah-Rempah, Aromatik/Penyegar, dan Obat Lainnya', 'Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman rempah lainnya, seperti kemiri, panili, kayu manis dan pala. Termasuk kegiatan pembibitan dan pembenihannya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0128', 'Perkebunan tanaman rempah-rempah, aromatik/penyegar, narkotik dan obat', '01289', 'Pertanian Tanaman Rempah-Rempah, Aromatik/Penyegar, dan Obat Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('77', '01291', 'Perkebunan Karet Dan Tanaman Penghasil Getah Lainnya', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman karet dan tanaman penghasil getah lainnya, seperti getah perca dan kemenyan. Termasuk pengolahan hasil tanaman karet yang tidak dapat dipisahkan dari kegiatan perkebunan. Termasuk kegiatan pembibitan dan pembenihan tanaman karet dan tanaman penghasil getah lainnya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0129', 'Perkebunan tanaman tahunan lainnya', '01291', 'Perkebunan Karet Dan Tanaman Penghasil Getah Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('78', '01299', 'Pertanian Cemara dan Tanaman Tahunan Lainnya', 'Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan pohon cemara, tanaman jarak pagar dan tanaman tahunan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman cemara dan tanaman tahunan lainnya.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '012', 'Pertanian tanaman tahunan', '0129', 'Perkebunan tanaman tahunan lainnya', '01299', 'Pertanian Cemara dan Tanaman Tahunan Lainnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('79', '01301', 'Pertanian Tanaman Hias ', 'Kelompok ini mencakup pertanian atau budidaya tanaman hias daun dan tanaman hias bunga hidup, seperti bonsai, suplir, kuping gajah, heliconia (pisang-pisangan), dracaena, phylodendrom, monstera, cordyline, anthurium daun, pakis, aglonema, difenbacia, sansifera (lidah mertua), caladium (keladi), palem dan tanaman hias bunga, seperti  anggrek, mawar, adenium (kaboja jepang, anthurium bunga, euphorbia, ixora (soka) dan tanaman bunga lainnya. Termasuk penanaman tumbuhan untuk tujuan ornamen dan tanah berumput untuk transplantasi.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '013', 'Pertanian Tanaman Hias Dan Pengembangbiakan Tanaman', '0130', 'Pertanian Tanaman Hias Dan Pengembangbiakan Tanaman', '01301', 'Pertanian Tanaman Hias ', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('80', '01302', 'Pertanian Pengembangbiakan Tanaman ', 'Kelompok ini mencakup produksi semua bibit tanaman secara vegetatif termasuk batang stek, potongan dan pembibitan untuk kelangsungan pengembangbiakan tanaman atau membuat batang okulasi tanaman pada keturunannya terpilih yang diokulasi yang pada akhirnya ditanam untuk menghasilkan tanaman. Termasuk kegiatan penanaman tumbuhan untuk ditanam kembali, penanaman tumbuhan hidup untuk umbi-umbian, akar-akaran; pemotongan, stek dan cangkokan; spawn jamur dan kebun bibit tanaman, kecuali kebun bibit tanaman hutan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '013', 'Pertanian Tanaman Hias Dan Pengembangbiakan Tanaman', '0130', 'Pertanian Tanaman Hias Dan Pengembangbiakan Tanaman', '01302', 'Pertanian Pengembangbiakan Tanaman ', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('81', '01411', 'Pembibitan Dan Budidaya Sapi Potong', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan sapi potong, untuk menghasilkan ternak bibit sapi potong, semen dan embrio, dan kegiatan budidaya sapi potong berupa  pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon sapi siap potong.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0141', 'Peternakan sapi dan kerbau', '01411', 'Pembibitan Dan Budidaya Sapi Potong', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('82', '01412', 'Pembibitan Dan Budidaya Sapi Perah', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan sapi perah untuk menghasilkan ternak bibit sapi perah, semen dan embrio dan usaha budidaya sapi perah berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan untuk menghasilkan susu dan penggemukan.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0141', 'Peternakan sapi dan kerbau', '01412', 'Pembibitan Dan Budidaya Sapi Perah', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('83', '01413', 'Pembibitan Dan Budidaya Kerbau Potong', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kerbau potong untuk menghasilkan ternak bibit kerbau potong, semen dan embrio dan usaha budidaya kerbau potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon kerbau siap potong.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0141', 'Peternakan sapi dan kerbau', '01413', 'Pembibitan Dan Budidaya Kerbau Potong', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('84', '01414', 'Pembibitan Dan Budidaya Kerbau Perah', 'Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan kerbau perah untuk menghasilkan ternak bibit kerbau perah, semen dan embrio dan usaha budidaya kerbau perah yang menyelenggarakan pengembangbiakan untuk menghasilkan anak atau calon indukan dan untuk menghasilkan susu. ', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0141', 'Peternakan sapi dan kerbau', '01414', 'Pembibitan Dan Budidaya Kerbau Perah', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('85', '01420', 'Peternakan Kuda dan Sejenisnya', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kuda dan sejenisnya, untuk menghasilkan ternak bibit kuda dan sejenisnya, semen dan embrio dan usaha budidaya kuda yang  melakukan kegiatan pengembangbiakan untuk menghasilkan kuda potong, kuda perah, kuda pacu, kuda tunggang, kuda tarik, kuda kavaleri, kuda polo, dan kuda kesayangan, bagal, hinni dan sejenisnya\n\nKelompok ini mencakup :\n-Produksi Susu Kuda dan Sejenisnya', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0142', 'Peternakan kuda dan sejenisnya', '01420', 'Peternakan Kuda dan Sejenisnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('86', '01430', 'Peternakan unta dan sejenisnya', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan unta dan sejenisnya untuk menghasilkan ternak bibit unta dan sejenisnya, semen dan embrio dan melakukan kegiatan budidaya unta berupa pengembangbiakan untuk menghasilkan unta potong, unta perah dan sejenisnya seperti llama, alpacas, vicunas dan guanacos.\n\nKelompok ini mencakup :\n- Produksi susu unta dan sejenisnya', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0143', 'Peternakan unta dan sejenisnya', '01430', 'Peternakan unta dan sejenisnya', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('87', '01441', 'Pembibitan Dan Budidaya Domba Potong', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan domba potong untuk menghasilkan ternak bibit domba potong, semen dan embrio dan kegiatan budidaya domba potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon domba siap potong.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0144', 'Peternakan domba dan kambing', '01441', 'Pembibitan Dan Budidaya Domba Potong', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
('88', '01442', 'Pembibitan Dan Budidaya Kambing Potong', 'Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kambing potong untuk menghasilkan ternak bibit kambing potong, semen dan embrio dan kegiatan budidaya kambing potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon kambing siap potong.', 'KBLI 2025', 'A', 'PERTANIAN, KEHUTANAN DAN PERIKANAN', '01', 'Pertanian Tanaman, Peternakan, Perburuan dan Kegiatan YBDI', '014', 'Peternakan', '0144', 'Peternakan domba dan kambing', '01442', 'Pembibitan Dan Budidaya Kambing Potong', 'A - PERTANIAN, KEHUTANAN DAN PERIKANAN', '1', '2026-08-31 04:35:47', '2026-08-31 04:35:47'),
