INSERT INTO `sertifikats` VALUES 
('2', '16', '5', 'SRT-2026-E4P2JU4X', 'Pelatihan Manajemen & Keuangan', 'Pelatihan ini akan membekali peserta dengan keterampilan teknis dalam perencanaan keuangan, pengelolaan arus kas, analisis laporan keuangan, serta strategi pengambilan keputusan berbasis data keuangan. Manfaat Training Dengan mengikuti pelatihan ini, peserta akan: Materi Training Metode Training', '2026-10-12', '2026-10-31', 'Laravel', 'sertifikats/j9mun8Bd9yiuoYAv8yMXIninXb6Ujo1NymPccbrh.jpg', 'A. Ade Indawan', 'Sertifikat adalah dokumen resmi yang diberikan sebagai bukti penghargaan, pencapaian, pelatihan, atau keikutsertaan, dan dapat dibuat atau diverifikasi melalui berbagai platform seperti Canva, PosterMyWall, atau sistem verifikasi sertifikat.', 'aktif', '2026-10-12 09:02:56', '2026-10-12 09:08:17', NULL, NULL);
