  `status_hadir` enum('hadir','izin','alpha') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `metode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `absensis_agenda_id_user_id_unique` (`agenda_id`,`user_id`),
  UNIQUE KEY `absensis_user_training_tanggal_unique` (`user_id`,`training_id`,`tanggal`),
  KEY `absensis_tanggal_index` (`tanggal`),
  KEY `absensis_status_index` (`status`),
  KEY `absensis_agenda_id_index` (`agenda_id`),
  KEY `absensis_training_id_index` (`training_id`),
  KEY `absensis_user_id_index` (`user_id`),
  CONSTRAINT `absensis_agenda_id_foreign` FOREIGN KEY (`agenda_id`) REFERENCES `agendas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `absensis_training_id_foreign` FOREIGN KEY (`training_id`) REFERENCES `trainings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `absensis_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `agendas`;
CREATE TABLE `agendas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
