  `tipe` enum('online','offline','hybrid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'online',
  `status` enum('draft','published','selesai','dibatalkan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `agendas_status_index` (`status`),
  KEY `agendas_tanggal_index` (`tanggal`),
  KEY `agendas_training_id_index` (`training_id`),
  KEY `agendas_tipe_index` (`tipe`),
  KEY `agendas_created_by_index` (`created_by`),
  KEY `agendas_tanggal_status_index` (`tanggal`,`status`),
  CONSTRAINT `agendas_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `agendas_training_id_foreign` FOREIGN KEY (`training_id`) REFERENCES `trainings` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


