DROP TABLE IF EXISTS `quiz_questions`;
CREATE TABLE `quiz_questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `quiz_id` bigint unsigned NOT NULL,
  `question` text COLLATE utf8mb4_unicode_ci COMMENT 'Pertanyaan (format baru)',
  `pertanyaan` text COLLATE utf8mb4_unicode_ci COMMENT 'Pertanyaan (format lama)',
  `type` enum('multiple_choice','true_false','essay') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'multiple_choice' COMMENT 'Tipe soal (format baru)',
  `tipe_soal` enum('pilihan','essay','true_false') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tipe soal (format lama)',
  `score` int NOT NULL DEFAULT '1' COMMENT 'Nilai per soal (format baru)',
  `nilai` int NOT NULL DEFAULT '1' COMMENT 'Nilai per soal (format lama)',
  `options` json DEFAULT NULL COMMENT 'Pilihan jawaban JSON (format baru)',
  `opsi_a` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Pilihan A (format lama)',
  `opsi_b` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Pilihan B (format lama)',
  `opsi_c` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Pilihan C (format lama)',
  `opsi_d` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Pilihan D (format lama)',
  `opsi_e` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Pilihan E (format lama)',
  `correct_answer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jawaban benar (format baru)',
  `jawaban_benar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jawaban benar (format lama)',
  `essay_answer_key` text COLLATE utf8mb4_unicode_ci,
  `order` int NOT NULL DEFAULT '0' COMMENT 'Urutan soal',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `quiz_questions_quiz_id_index` (`quiz_id`),
  KEY `quiz_questions_type_index` (`type`),
  KEY `quiz_questions_tipe_soal_index` (`tipe_soal`),
  KEY `quiz_questions_order_index` (`order`),
  KEY `quiz_questions_score_index` (`score`),
  CONSTRAINT `quiz_questions_quiz_id_foreign` FOREIGN KEY (`quiz_id`) REFERENCES `quizzes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


