  UNIQUE KEY `user_kblis_user_id_kbli_id_unique` (`user_id`,`kbli_id`),
  KEY `user_kblis_kbli_id_foreign` (`kbli_id`),
  CONSTRAINT `user_kblis_kbli_id_foreign` FOREIGN KEY (`kbli_id`) REFERENCES `kblis` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_kblis_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


